SENSITIVE_ACTIONS = {'send_email', 'delete_file', 'transfer_funds'}

def policy_gate(action, approved_by_user=False, allowed_recipient=False):
    if action in SENSITIVE_ACTIONS and not approved_by_user:
        return 'BLOCK: explicit approval required'
    if action == 'send_email' and not allowed_recipient:
        return 'BLOCK: recipient not allowlisted'
    return 'PASS POLICY CHECK; continue with authorization and validation'
